def solve(inputs: dict) -> float:
    # Terms passed as individual inputs T0..T6
    terms = []
    i = 0
    while f'T{i}' in inputs:
        terms.append(int(inputs[f'T{i}']))
        i += 1

    if not terms:
        return 0

    p_prev = 1  # p_{-1}
    p_curr = terms[0]  # p_0

    for k in range(1, len(terms)):
        p_next = terms[k] * p_curr + p_prev
        p_prev = p_curr
        p_curr = p_next

    print(f"Numerator: {p_curr}")
    return float(p_curr)

